pragma solidity ^0.8.17;

import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    RoundFactory c;

    function setUp() public {
        c = new RoundFactory();
    }

    function _run(address newAlloSettings) internal {
        vm.assume(true);
        bool reverted;
        try c.updateAlloSettings(newAlloSettings) { reverted = false; } catch { reverted = true; }
        assertTrue(!reverted == (c.owner() == address(this)));
    }

    function testFuzz_run(address newAlloSettings) public {
        _run(newAlloSettings);
    }

    receive() external payable {}
}
